import os, json, sqlite3, secrets, re
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlsplit
from pathlib import Path

DATA = os.environ.get("DATA_DIR", "/data")
os.makedirs(DATA, exist_ok=True)
DB = DATA + "/links.sqlite3"
def connect():
    db = sqlite3.connect(DB, timeout=20)
    db.execute("CREATE TABLE IF NOT EXISTS links (slug TEXT PRIMARY KEY, url TEXT NOT NULL, created TEXT DEFAULT CURRENT_TIMESTAMP)")
    return db
with connect(): pass

def create_link(url, alias):
    if not isinstance(url, str) or len(url)>16000: raise ValueError("Enter a valid URL.")
    url=url.strip()
    try:
        parsed=urlsplit(url)
        if parsed.scheme not in ("http","https") or not parsed.hostname or parsed.username or parsed.password or any(ord(c)<33 for c in url): raise ValueError()
        parsed.port
    except ValueError: raise ValueError("Use a complete http:// or https:// URL without credentials or spaces.")
    if not isinstance(alias,str): raise ValueError("Invalid custom name.")
    alias=alias.strip()
    if alias and (not re.fullmatch(r"[a-zA-Z0-9_-]{3,48}",alias) or alias.lower() in ("api","health","favicon.ico")):
        raise ValueError("Custom names need 3–48 letters, numbers, hyphens or underscores.")
    with connect() as db:
        for _ in range(10):
            slug=alias or secrets.token_urlsafe(5)
            try:
                db.execute("INSERT INTO links(slug,url) VALUES (?,?)",(slug,url))
                return {"slug":slug,"url":url}
            except sqlite3.IntegrityError:
                if alias: raise ValueError("That custom name is taken. Try another.")
    raise ValueError("Please try again.")

class Handler(BaseHTTPRequestHandler):
    def send(self,status,body,kind="application/json",extra=None):
        if not isinstance(body,bytes): body=json.dumps(body).encode()
        self.send_response(status)
        self.send_header("Content-Type",kind)
        self.send_header("Content-Length",str(len(body)))
        self.send_header("X-Content-Type-Options","nosniff")
        self.send_header("Cache-Control","no-store")
        for k,v in (extra or {}).items(): self.send_header(k,v)
        self.end_headers()
        if self.command!="HEAD": self.wfile.write(body)
    def do_HEAD(self): self.do_GET()
    def do_GET(self):
        path=urlsplit(self.path).path
        if path=="/": return self.send(200,Path("index.html").read_bytes(),"text/html; charset=utf-8")
        if path=="/health": return self.send(200,{"ok":True})
        slug=path[1:]
        if not re.fullmatch(r"[a-zA-Z0-9_-]{3,48}",slug): return self.send(404,{"error":"Link not found"})
        with connect() as db: row=db.execute("SELECT url FROM links WHERE slug=?",(slug,)).fetchone()
        if row: return self.send(302,b"","text/plain",{"Location":row[0],"Referrer-Policy":"no-referrer"})
        return self.send(404,b"That short link does not exist. Check the address or create one from the home page.","text/plain")
    def do_POST(self):
        if self.path!="/api/links": return self.send(404,{"error":"Not found"})
        try:
            size=int(self.headers.get("Content-Length","0"))
            if size<=0 or size>20000: return self.send(413,{"error":"URL is too large or missing."})
            body=json.loads(self.rfile.read(size))
            if not isinstance(body,dict): raise ValueError("Invalid request.")
            result=create_link(body.get("url",""),body.get("alias",""))
            return self.send(201,result)
        except (ValueError,UnicodeError) as e: return self.send(400,{"error":str(e)})
        except Exception:
            return self.send(500,{"error":"Could not save your link. Please try again."})
if __name__=="__main__":
    print("Link shortener ready on port 8080",flush=True)
    ThreadingHTTPServer(("0.0.0.0",8080),Handler).serve_forever()

import unittest, tempfile, os, importlib
os.environ["DATA_DIR"]=tempfile.mkdtemp()
import server
class Tests(unittest.TestCase):
    def test_create_persist(self):
        item=server.create_link("https://example.com/a?b=c","notes")
        with server.connect() as db:
            self.assertEqual(db.execute("SELECT url FROM links WHERE slug=?",(item["slug"],)).fetchone()[0],"https://example.com/a?b=c")
        with self.assertRaises(ValueError): server.create_link("https://example.com","notes")
    def test_validation(self):
        for url in ["javascript:alert(1)","https://","ftp://example.com","https://a.com/\r\nx","https://user:pass@example.com"]:
            with self.assertRaises(ValueError): server.create_link(url,"")
        with self.assertRaises(ValueError): server.create_link("https://example.com","../x")
    def test_unique(self):
        self.assertEqual(len({server.create_link("https://example.com","")["slug"] for _ in range(50)}),50)
if __name__=="__main__": unittest.main()

